/**
 * Frequency-ordered dictionaries for the password strength estimator
 * (./passwordStrength.ts).
 *
 * A word's position is its rank, which is what the estimate costs an
 * attacker: guessing `monkey` takes about 15 tries because it is the
 * 15th most common leaked password. Order therefore matters, and the
 * lists must not be sorted.
 *
 * Derived from the frequency lists of zxcvbn (Dropbox, MIT licence),
 * which were built from leaked password dumps, Wikipedia, US TV and
 * film subtitles and US census names:
 * https://github.com/dropbox/zxcvbn
 *
 * Each list is stored comma-separated and split at module load. Only
 * ./passwordStrength.ts imports this file, so bundles that merely
 * generate passwords never pay for it.
 */

